add_filter( 'woocommerce_form_field', 'perfectpixel_remove_optional_label', 10, 4 );

function perfectpixel_remove_optional_label( $field, $key, $args, $value ) {
	if ( function_exists( 'is_checkout' ) && is_checkout() && ! is_wc_endpoint_url() ) {
		$field = preg_replace( '#\s*<span class="optional">.*?</span>#s', '', $field );
	}
	return $field;
}
